import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import logo from "./assets/logo.png";
import { FaSearch, FaChevronDown } from 'react-icons/fa';

const Header = () => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen);
  };

  const toggleSearch = () => {
    setIsSearchOpen(!isSearchOpen);
    if (isSearchOpen) {
      setSearchQuery('');
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    // Handle search functionality here
    console.log('Searching for:', searchQuery);
    setIsSearchOpen(false);
    setSearchQuery('');
  };

  return (
    <header className="header">
      <div className="logoContainer">
        <Link to="/">
          <img src={logo} alt="AIM-Binance Logo" className="logo" />
        </Link>
        <div className="brandName">AIM-Binance</div>
      </div>
      
      <div className="headerControls">
        {/* Search Bar - appears when search is clicked */}
        {isSearchOpen && (
          <form className="searchForm" onSubmit={handleSearchSubmit}>
            <input
              type="text"
              placeholder="Search..."
              value={searchQuery}
              onChange={handleSearchChange}
              className="searchInput"
              autoFocus
            />
          </form>
        )}
        
        {/* Search Icon */}
        <button className="searchIcon" onClick={toggleSearch}>
          <FaSearch />
        </button>
        
        {/* Dropdown Menu */}
        <div className="dropdownContainer">
          <button className="dropdownToggle" onClick={toggleDropdown}>
            <span>Menu</span>
            <FaChevronDown className={`dropdownArrow ${isDropdownOpen ? 'open' : ''}`} />
          </button>
          
          {isDropdownOpen && (
            <ul className="dropdownMenu">
              <li className="dropdownItem">
                <Link to="/login" className="dropdownLink" onClick={toggleDropdown}>Login</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/signup" className="dropdownLink" onClick={toggleDropdown}>Sign Up</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/support" className="dropdownLink" onClick={toggleDropdown}>Support</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/admin-login" className="dropdownLink" onClick={toggleDropdown}>Admin Login</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/#market-overview" className="dropdownLink" onClick={toggleDropdown}>Market Overview</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/#trending-coins" className="dropdownLink" onClick={toggleDropdown}>Trending Coins</Link>
              </li>
              <li className="dropdownItem">
                <Link to="/#faq" className="dropdownLink" onClick={toggleDropdown}>FAQ</Link>
              </li>
            </ul>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;
